llmStructuredOutput.jsonSchema:
{
  "roleTitle": {
    "type": "string",
    "description": "Job title of the critical role"
  },
  "roleId": {
    "type": "string",
    "description": "Unique identifier (e.g., CR-001)"
  },
  "department": {
    "type": "string",
    "description": "Department name"
  },
  "incumbentName": {
    "type": "string",
    "description": "Current holder's name"
  },
  "incumbentTenure": {
    "type": "number",
    "description": "Years in role"
  },
  "flightRisk": {
    "type": "number",
    "description": "Percentage (0-100)"
  },
  "criticalityScore": {
    "type": "number",
    "description": "Score from 1-100"
  },
  "successionUrgency": {
    "type": "string",
    "description": "Critical, High, Medium, or Low"
  }
}
